def __call__(self, question: str) -> PipelineResult:
    import logging

    ctx = {"question": question}
    intermediate = {}

    for name, component in self.components:
        try:
            output = component.forward(**ctx)
            if not isinstance(output, dict):
                logging.warning(f"Component {name} returned non-dict output: {output}")
                output = {}
            ctx.update(output)
            intermediate[name] = output
        except Exception as e:
            logging.error(f"Error in component {name}: {e}", exc_info=True)
            intermediate[name] = {"error": str(e)}
            break

    return PipelineResult(
        answer=ctx.get("answer", ""),
        intermediate=intermediate,
    )

